#include "traffic_framer.h"
#include <algorithm>
bool TrafficFramer::configure(TrafficFraming c,std::string& error){if(static_cast<unsigned>(c.mode)>TrafficFraming::HeaderFixed||c.bytes<1||c.bytes>65536||c.idle_ms<1||c.idle_ms>60000||c.header.size()>32||(c.mode==TrafficFraming::HeaderFixed&&(c.header.empty()||c.bytes<c.header.size()))){error="Frame bytes 1..65536, idle 1..60000 ms; header 1..32 bytes and no longer than the fixed frame.";return false;}config_=std::move(c);reset();return true;}
void TrafficFramer::reset(){for(auto& p:pending_){p.bytes.clear();p.spans.clear();}discarded_=0;}
TrafficRecord TrafficFramer::consume(Pending& p,size_t count,bool keep){TrafficRecord out;const auto total=count;if(keep)out.bytes=p.bytes.substr(0,count);while(count&&!p.spans.empty()){auto& span=p.spans.front();const auto n=std::min(count,span.count);if(!out.first_sequence){out.first_sequence=span.receipt.first_sequence?span.receipt.first_sequence:span.receipt.sequence;out.first_offset=span.offset;}out.last_offset=span.offset+n;span.offset+=n;out.sequence=span.receipt.sequence;out.receipt_ms=span.receipt.receipt_ms;out.sample_seconds=span.receipt.sample_seconds;out.generation=span.receipt.generation;out.tx=span.receipt.tx;span.count-=n;count-=n;if(!span.count)p.spans.pop_front();}p.bytes.erase(0,total);return out;}
std::vector<TrafficRecord> TrafficFramer::extract(size_t direction,double now){auto& p=pending_[direction];std::vector<TrafficRecord> out;
    while(!p.bytes.empty()&&out.size()<256){size_t count=0;if(config_.mode==TrafficFraming::LF||config_.mode==TrafficFraming::CRLF){const auto end=p.bytes.find(config_.mode==TrafficFraming::LF?"\n":"\r\n");if(end==std::string::npos)break;count=end+(config_.mode==TrafficFraming::LF?1:2);}
        else if(config_.mode==TrafficFraming::Idle){if(p.spans.empty()||now-p.spans.back().receipt.sample_seconds<config_.idle_ms/1000.0)break;count=p.bytes.size();}
        else {if(config_.mode==TrafficFraming::HeaderFixed){const auto at=p.bytes.find(config_.header);if(at==std::string::npos){const auto keep=std::min(p.bytes.size(),config_.header.size()-1);discarded_+=p.bytes.size()-keep;consume(p,p.bytes.size()-keep,false);break;}if(at){discarded_+=at;consume(p,at,false);}}if(p.bytes.size()<config_.bytes)break;count=config_.bytes;}
        out.push_back(consume(p,count));
    }return out;
}
std::vector<TrafficRecord> TrafficFramer::feed(const TrafficRecord& record){if(config_.mode==TrafficFraming::Chunks)return {record};const auto direction=record.tx?1:0;auto& p=pending_[direction];std::vector<TrafficRecord> out;if(p.generation!=record.generation){discarded_+=p.bytes.size();p={};p.generation=record.generation;}
    if(config_.mode==TrafficFraming::Idle&&!p.bytes.empty()&&!p.spans.empty()&&record.sample_seconds-p.spans.back().receipt.sample_seconds>=config_.idle_ms/1000.0)out.push_back(consume(p,p.bytes.size()));
    if(record.bytes.size()>65536){discarded_+=record.bytes.size()+p.bytes.size();p={};return out;}if(p.bytes.size()+record.bytes.size()>65536||p.spans.size()>=2048){discarded_+=p.bytes.size();p={};}
    p.generation=record.generation;if(!record.bytes.empty()){p.bytes+=record.bytes;TrafficRecord receipt;receipt.sequence=record.sequence;receipt.receipt_ms=record.receipt_ms;receipt.tx=record.tx;receipt.sample_seconds=record.sample_seconds;receipt.generation=record.generation;p.spans.push_back({record.bytes.size(),std::move(receipt),record.first_offset});}auto extracted=extract(direction,record.sample_seconds);out.insert(out.end(),std::make_move_iterator(extracted.begin()),std::make_move_iterator(extracted.end()));return out;
}
std::vector<TrafficRecord> TrafficFramer::drain(double now){if(config_.mode==TrafficFraming::Chunks)return {};auto out=extract(0,now),tx=extract(1,now);out.insert(out.end(),std::make_move_iterator(tx.begin()),std::make_move_iterator(tx.end()));std::stable_sort(out.begin(),out.end(),[](const auto& a,const auto& b){return a.sample_seconds<b.sample_seconds;});return out;}
